const roles={owner:{name:'业主空间',desc:'我的家，由我开始',heading:'林同学，欢迎回家',sub:'从一个想法，到每一处细节。一起把理想的家慢慢实现。'},designer:{name:'设计师工作台',desc:'让设计，有落地的答案',heading:'今天，让好设计发生',sub:'整理灵感、打磨方案，与材料和施工伙伴一起交付。'},supplier:{name:'材料商工作台',desc:'把好材料，送到合适的家',heading:'每一份好材料，都值得被看见',sub:'管理商品与询价，让选材、交期和交付更有把握。'},builder:{name:'施工协作台',desc:'每一道工序，都有回应',heading:'今天的工程，安排妥当',sub:'查看排期、确认材料、记录现场，让每个节点清楚可见。'},inspector:{name:'监理工作台',desc:'用记录，守住交付标准',heading:'把质量，落在每一个细节',sub:'检查、留证、整改与复验，让每个结论都有依据。'}};
const initial={role:'owner',project:'南山 · 林间小家',budget:180000,room:'全部空间',category:'全部',query:'',events:[],favorites:[],selected:[],compare:[],todos:{},personalized:true,modelOn:true,deletedTags:[],snapshots:[],impressions:[],tasks:{},inquiries:[],requests:[],view:'home'};
let saved;try{saved=JSON.parse(localStorage.getItem('qiju-prototype-v1')||'null')}catch{};
let state={...initial,...saved};let roomFilter=state.room,category=state.category,query=state.query,sort='recommend',onlyStock=false;let lastFocus, toastTimer, pendingProduct=null;
const TAGS=[...new Set(products.flatMap(p=>p.tags))],D=TAGS.length+1;
function features(p){let x=Array(D).fill(0);x[0]=1;p.tags.forEach(t=>x[TAGS.indexOf(t)+1]=1/Math.sqrt(p.tags.length));return x;}
function fitModel(){let A=Array.from({length:D},(_,i)=>Array.from({length:D},(_,j)=>i===j?1:0)),b=Array(D).fill(0);for(const e of state.events.filter(e=>!e.retracted)){let x=e.x;if(!x||x.length!==D)continue;let ax=A.map(r=>r.reduce((s,v,j)=>s+v*x[j],0)),den=1+x.reduce((s,v,i)=>s+v*ax[i],0);A=A.map((r,i)=>r.map((v,j)=>v-ax[i]*ax[j]/den));b=b.map((v,i)=>v+e.reward*x[i]);}let theta=A.map(r=>r.reduce((s,v,i)=>s+v*b[i],0));return {A,theta};}
function score(p,model){let x=features(p),v=x.reduce((s,a,i)=>s+a*model.theta[i],0),confidence=Math.sqrt(Math.max(0,x.reduce((s,a,i)=>s+a*model.A[i].reduce((z,b,j)=>z+b*x[j],0),0)));let confirmed=confirmedTags();return v+.15*confidence+.12*p.tags.filter(t=>confirmed.includes(t)).length;}
function confirmedTags(){return [...new Set(state.events.filter(e=>!e.retracted&&e.kind==='confirm').flatMap(e=>e.tags||[]))].filter(t=>!state.deletedTags.includes(t));}
function persist(){try{localStorage.setItem('qiju-prototype-v1',JSON.stringify(state));}catch{toast('浏览器存储空间不足，本次更改未保存');}}
function snapshot(){state.snapshots.push({events:structuredClone(state.events),deletedTags:[...state.deletedTags],time:Date.now()});state.snapshots=state.snapshots.slice(-30);}
function learn(p,kind,reward,tags){snapshot();let x=features(p);if(tags){x=Array(D).fill(0);tags.forEach(t=>x[TAGS.indexOf(t)+1]=1/Math.sqrt(tags.length||1));state.deletedTags=state.deletedTags.filter(t=>!tags.includes(t));}state.events.push({id:crypto.randomUUID(),product:p.id,name:p.name,kind,reward,x,tags:tags||p.tags,time:Date.now(),room:roomFilter,retracted:false});persist();}
function rank(list,log=true){if(!state.personalized||!state.modelOn||sort!=='recommend')return list;const m=fitModel(),remaining=[...list],ordered=[];const trace=[];while(remaining.length){let best=remaining.reduce((a,b)=>score(a,m)>=score(b,m)?a:b),eps=.15,explore=Math.random()<eps;let selected=explore?remaining[Math.floor(Math.random()*remaining.length)]:best;trace.push({id:selected.id,p:eps/remaining.length+(selected.id===best.id?1-eps:0),explore});ordered.push({...selected,explore});remaining.splice(remaining.findIndex(p=>p.id===selected.id),1);}if(log){state.impressions.push({id:crypto.randomUUID(),time:Date.now(),room:roomFilter,category,trace,modelVersion:state.events.filter(e=>!e.retracted).length});state.impressions=state.impressions.slice(-120);persist();}return ordered;}
const money=n=>Number(n).toLocaleString('zh-CN');
