function intro(eye,title,sub,buttons=''){return `<div class="page-intro"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p>${sub}</p></div><div class="button-row">${buttons}</div></div>`;}
function render(){nav();document.body.classList.remove('menu-open');const space=state.view==='space';$('#content').hidden=space;$('#space-page').hidden=!space;document.body.classList.toggle('studio-full',space&&!!state.fullscreen);if(space){renderSpace();return;}const views={home:renderHome,market:renderMarket,partners:renderPartners,project:renderProject,budget:renderBudget,preferences:renderPreferences,assets:renderAssets};$('#content').innerHTML=`<div class="page-enter">${(views[state.view]||renderHome)()}</div>`;updateCompare();}
function route(view){state.view=view;persist();if(location.hash!=='#'+view)location.hash=view;else render();window.scrollTo({top:0,behavior:'smooth'});}
function productCard(p){const fav=state.favorites.includes(p.id),selected=state.selected.includes(p.id),matched=p.tags.filter(t=>confirmedTags().includes(t));return `<article class="product-card reveal"><div class="product-image"><button class="heart ${fav?'selected':''}" data-action="favorite" data-id="${p.id}" aria-label="${fav?'取消收藏':'收藏'}${p.name}" aria-pressed="${fav}">${fav?'♥':'♡'}</button><button style="display:block;width:100%;padding:0" data-action="product" data-id="${p.id}">${slot(p.image,p.size+' · 4:3',p.tone)}</button></div><div class="product-info"><h3>${p.name}</h3><p>${p.spec}</p><div class="price-line"><span class="price">¥${money(p.price)}<small> / ${p.unit}</small></span><button class="text-button" style="font-size:10px" data-action="compare" data-id="${p.id}">${state.compare.includes(p.id)?'已对比':'＋ 对比'}</button></div><div class="reason">✧ ${p.explore?'探索推荐 · 发现另一种可能':matched.length?'符合你的'+matched.slice(0,2).join('、')+'偏好':'适配空间 · 可询价核实'}</div><div class="card-actions"><button data-action="feedback" data-id="${p.id}">调整推荐</button><button data-action="select-product" data-id="${p.id}">${selected?'✓ 已加入方案':'＋ 加入方案'}</button></div></div></article>`;}
function renderHome(){if(state.role!=='owner')return renderRoleHome();let rec=rank(products).slice(0,4);return `<section class="hello"><div><h1>${roles.owner.heading} <span style="font-size:20px">☀</span></h1><p>${roles.owner.sub}</p></div><span class="date">把今天，留给喜欢的生活。</span></section><section class="hero"><div class="hero-copy"><div class="eyebrow">A LITTLE CLOSER TO YOUR DREAM HOME</div><h1>家的模样，<br>从你的<em>喜欢</em>开始。</h1><p>上传户型，走进未来的家。<br>让灵感、好材料和靠谱的人，在这里相遇。</p><div class="button-row"><button class="primary" data-route="space">进入我的三维空间 <span>↗</span></button><button class="outline" data-action="new-project">＋ 创建新项目</button></div></div><div class="hero-art"><div class="floating-note">✧ 一点灵感，慢慢变成家</div>${floorArt()}<div class="floating-note two">⌂ 从户型，到真实生活</div><span class="art-note">结构示意 · 可替换为你的空间渲染图</span></div></section><div class="quick-grid">${[['space','户型与三维','看看家的每一个角落'],['market','挑选好材料','把喜欢放进方案'],['partners','找到对的人','设计 · 施工 · 监理'],['budget','算清每一笔','预算与费用更清晰'],['project','一起把家做好','每个进度都看得见']].map(([id,a,b])=>`<button class="quick-card" data-route="${id}"><span class="quick-icon">${icon(id)}</span><span><b>${a}</b><small>${b}</small></span></button>`).join('')}</div><div class="home-two"><section><div class="section-head"><h2>继续我的家</h2><button class="text-button" data-route="project">项目详情 ↗</button></div><div class="panel project-preview">${slot('项目客厅效果图','600 × 450 · 4:3')}<div class="project-meta"><span class="pill purple">方案打磨中</span><h3>${esc(state.project)}</h3><div class="meta-row"><span>三室两厅</span><span>108 ㎡</span><span>全屋焕新</span></div><div class="progress-label"><span>设计确认</span><span>第 2 / 6 阶段</span></div><div class="progress-track"><span style="width:32%"></span></div><div class="project-bottom"><div class="avatar-stack"><span>林</span><span>陈</span><span>周</span></div><button class="text-button" data-route="space">继续完善 →</button></div></div></div></section><section><div class="section-head"><h2>等你的小决定</h2><span class="label-muted">不着急，一步一步来</span></div><div class="panel" style="padding-top:8px;padding-bottom:8px">${[['t1','确认客厅地面材料','2 款材料待比较','market'],['t2','查看设计师的新方案','陈设计师 · 方案 V2','space'],['t3','核对第一版预算','还有 3 项待现场核实','budget']].map(([id,a,b,r])=>`<div class="todo ${state.todos[id]?'done':''}"><button class="todo-check" data-action="todo" data-id="${id}" aria-label="${state.todos[id]?'取消完成':'标记完成'}${a}">${state.todos[id]?'✓':''}</button><span><b>${a}</b><small>${b}</small></span><button class="text-button" data-route="${r}">查看 →</button></div>`).join('')}</div></section></div><section><div class="section-head"><div><h2>慢慢挑，都是生活的细节</h2><p>从一块地板、一盏灯，找到适合你的那一种。</p></div><button class="text-button" data-route="market">探索全部好物 ↗</button></div><div class="tabs">${['为你发现','瓷砖石材','地板板材','家具软装','厨卫设备'].map((t,i)=>`<button class="tab ${i===0?'active':''}" data-action="home-category" data-value="${t}">${t}</button>`).join('')}</div><div class="card-grid">${rec.map(productCard).join('')}</div></section>${learningStrip()}<div class="section-head" style="margin-top:27px"><div><h2>家有不同角色，心有同一个方向</h2><p>设计有回应，材料有着落，施工有交代。</p></div><button class="text-button" id="home-role">切换工作台 ↗</button></div><div class="quick-grid role-grid" style="grid-template-columns:repeat(4,1fr)">${Object.entries(roles).filter(([k])=>k!=='owner').map(([k,r])=>`<button class="quick-card" data-action="role" data-id="${k}"><span class="quick-icon">${icon(k==='designer'?'preferences':k==='supplier'?'market':k==='inspector'?'project':'partners')}</span><span><b>${r.name}</b><small>${r.desc}</small></span></button>`).join('')}</div>`;}
